window.kbPageData["views/entry/k-7710ae6ce7fdca2f"] = {"key":"entry/k-7710ae6ce7fdca2f","state":{"route":"entry/k-7710ae6ce7fdca2f"},"node":{"id":"k-7710ae6ce7fdca2f","mode":"k","title":"耕地保护红线","type":"制度与规则","domain":"生态环境","reading":"","intro":"","priority":100,"aliases":["耕地红线","农业强国规划中的耕地保护红线"],"qs":["政治理论必刷100题#37","江苏 2024 C类 申论#3"],"current":true,"candidates":false,"basisGroup":"","authority":null,"sourceOnly":false,"repeatPositions":0,"reviewSet":"多题条目","independentCount":2,"tags":{"专题":["rural"],"主类":["制度与规则"],"出处性质":["专项题解析","机构注释"],"学科":["公共管理","生态环境"],"来源主题":["农业与城乡治理"],"资料类别":["政治理论专项","非时政"]},"directorySummary":"耕地保护红线是国家为保障粮食安全而设定的耕地保有面积底线。《加快建设农业强国规划（2024—2035年）》要求守牢18.65亿亩耕地和15.46亿亩永久基本农田保护红线。","review":{"title":"耕地保护红线","type":"制度与规则","definition":"耕地保护红线是国家为保障粮食安全而设定的耕地保有面积底线。《加快建设农业强国规划（2024—2035年）》要求守牢18.65亿亩耕地和15.46亿亩永久基本农田保护红线。","explanation":"永久基本农田属于耕地，两项面积是各自适用范围内的保护底线。党的二十大报告提出“牢牢守住十八亿亩耕地红线”，农业强国规划在全面加强耕地保护和建设的部署中列出了两项具体面积要求。","basis":"据关联原题及所列出处编释。","references":[{"source":"farm","location":"严守耕地红线"}],"related":["k-7f4a4aba9435a8e5","k-caedc47bc4c7745b"],"domain":"生态环境","examFocus":{"政治理论必刷100题#37":"对照农业强国建设规划的任务划分，核对耕地和永久基本农田保护、农产品外贸及加工举措分别归在哪一项任务下。","江苏 2024 C类 申论#3":"从给定资料6找出耕地保护和防止耕地“非粮化”的政策依据，结合F村基本农田种藕的情况，向村民说明为何要退藕还稻。"}},"aspects":[{"title":"农业强国规划的两项面积要求","uses":[{"unit":"Q1","role":"直接考查","use":"本题的③列出耕地和永久基本农田的保护面积要求。该举措列在规划的“全方位夯实粮食安全根基，把中国人的饭碗端得更牢更稳”部分，与①⑤同属题问范围，共3项，选B。","evidence":"守牢 18.65 亿亩耕地和 15.46 亿亩永久基本农田保护红线","qids":["政治理论必刷100题#37"]}]},{"title":"退藕还稻的政策依据","uses":[{"unit":"Q2","role":"解题依据","use":"本题要求以F村村“两委”名义写公开信。材料中孙副镇长援引党的二十大报告的十八亿亩耕地红线要求，并提到县里的防止耕地“非粮化”工作方案，可结合F村基本农田种藕蔓延的情况说明退藕还稻的必要性。","evidence":"牢牢守住十八亿亩耕地红线","qids":["江苏 2024 C类 申论#3"]}]}],"sources":[{"id":"ac62f51740fec606","label":"耕地红线","topic":"农业与城乡治理","category":"非时政","text":"4.耕地红线\n耕地红线是指经常进行耕种的土地面积的最低值，守住耕地红线旨在确保国家粮食安全。\n国务院印发《全国土地利用总体规划纲要（2006—2020 年）》提出，确保 18 亿亩的耕地红\n线。","source":{"doc":"6cbfb01fe723bba64b75","first":34,"last":34,"page":34,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"questions":{"政治理论必刷100题#37":{"paper":"政治理论必刷100题","n":37,"mod":"政治理论专项","src":["国省考政治理论必刷100题.pdf",11],"asrc":["国省考政治理论必刷100题.pdf",54],"card":"5437719768ca8ab16463a2c3","links":[{"id":"k-7710ae6ce7fdca2f","role":"直接考查","why":"规划明确两类保护红线的具体面积，并将其列入粮食安全任务。"}]},"江苏 2024 C类 申论#3":{"paper":"江苏 2024 C类 申论","n":3,"mod":"申论","src":["a7cfdee83e6ff0de5e71.pdf",3],"asrc":["525cbf0b49bf46168baf.pdf",2],"card":"34937ce9d0604e011b46a569","links":[{"id":"k-7710ae6ce7fdca2f","role":"解题依据","why":"守住十八亿亩耕地红线是夯实粮食安全根基的政策要求，为说明F村退藕还稻的必要性提供依据。"}]}},"terms":{"k-7f4a4aba9435a8e5":{"id":"k-7f4a4aba9435a8e5","mode":"k","type":"制度与规则","title":"省级政府的耕地保护责任","qs":[],"count":2},"k-caedc47bc4c7745b":{"id":"k-caedc47bc4c7745b","mode":"k","type":"制度与规则","title":"耕地数量、质量、生态“三位一体”保护","qs":[],"count":2}},"references":{"farm":{"name":"《加快建设农业强国规划（2024—2035年）》","url":"https://app.www.gov.cn/govdata/gov/202504/07/526167/article.html"}},"topics":[{"slug":"rural","title":"乡村振兴与粮食安全"}],"units":{"k-7710ae6ce7fdca2f":[["政治理论必刷100题#37"],["江苏 2024 C类 申论#3"]]}};
